export function parseMultisigCreateInstruction<
	TProgram extends string,
	TAccountMetas extends readonly AccountMeta[],
>(
	instruction:
		& Instruction<TProgram>
		& InstructionWithAccounts<TAccountMetas>
		& InstructionWithData<ReadonlyUint8Array>,
): ParsedMultisigCreateInstruction<TProgram, TAccountMetas> {
	if (instruction.accounts.length < 7) {
		throw new SolanaError(
			SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
			{
				actualAccountMetas: instruction.accounts.length,
				expectedAccountMetas: 7,
			},
		);
	}
	let accountIndex = 0;
	const getNextAccount = () => {
		const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
		accountIndex += 1;
		return accountMeta;
	};
	const getNextOptionalAccount = () => {
		const accountMeta = getNextAccount();
		return accountMeta.address === instruction.programAddress
			? undefined
			: accountMeta;
	};
	return {
		programAddress: instruction.programAddress,
		accounts: {
			programConfig: getNextAccount(),
			createKey: getNextAccount(),
			multisig: getNextAccount(),
			rentPayer: getNextAccount(),
			systemProgram: getNextAccount(),
			treasury: getNextOptionalAccount(),
			memberAccounts: getNextAccount(),
		},
		data: getMultisigCreateInstructionDataDecoder().decode(instruction.data),
	};
}
